import assert from 'node:assert/strict';
import { test } from 'vitest';
import { createGame, activateCard } from './game.ts';
import { DEAL_NAME_MAX_LENGTH, isValidDealName } from './deal-name.ts';
import { isJsonObject } from './saved-format.ts';
import {
  decodeSnapshot,
  encodeSnapshot,
  NAMED_SNAPSHOT_VERSION,
  SNAPSHOT_VERSION,
} from './snapshot.ts';
import { EXAMPLE_CODE } from './game.fixture.ts';

test('unnamed progress keeps version one and named progress round trips as version two', () => {
  const unnamed = createGame(EXAMPLE_CODE);
  const plain: unknown = JSON.parse(encodeSnapshot(unnamed));
  assert.ok(isJsonObject(plain));
  assert.equal(plain.version, SNAPSHOT_VERSION);
  assert.equal(Object.hasOwn(plain, 'name'), false);
  assert.equal(decodeSnapshot(encodeSnapshot(unnamed))?.name, '');

  const named = activateCard({ ...unnamed, name: ' Café ' }, 0);
  const exported: unknown = JSON.parse(encodeSnapshot(named));
  assert.ok(isJsonObject(exported));
  assert.equal(exported.version, NAMED_SNAPSHOT_VERSION);
  assert.equal(exported.name, ' Café ');
  assert.deepEqual(decodeSnapshot(encodeSnapshot(named)), named);
});

test('valid snapshot fields may appear in any order', () => {
  const versionOne = JSON.stringify({
    started: true,
    boardCode: EXAMPLE_CODE,
    elapsedMs: 0,
    selection: { index: 2, kind: 'one' },
    matched: [],
    moves: 0,
    version: 1,
  });
  const versionTwo = JSON.stringify({
    name: 'saved run',
    started: true,
    selection: { kind: 'one', index: 2 },
    moves: 0,
    version: 2,
    matched: [],
    elapsedMs: 0,
    boardCode: EXAMPLE_CODE,
  });
  assert.equal(decodeSnapshot(versionOne)?.selection.kind, 'one');
  assert.equal(decodeSnapshot(versionTwo)?.name, 'saved run');
  assert.equal(decodeSnapshot(versionTwo)?.selection.kind, 'one');
});

test('version one clears names and both snapshot schemas remain strict', () => {
  const legacy = JSON.stringify({
    boardCode: EXAMPLE_CODE,
    matched: [],
    selection: { kind: 'closed' },
    moves: 0,
    elapsedMs: 0,
    started: false,
    version: 1,
  });
  const invalid = [
    legacy.replace('"version":1', '"version":1,"extra":true'),
    legacy.replace('"version":1', '"version":1,"name":"wrong version field"'),
    legacy.replace('"version":1', '"version":2'),
    legacy.replace('"version":1', '"version":3'),
  ];
  assert.equal(decodeSnapshot(legacy)?.name, '');
  for (const text of invalid) assert.equal(decodeSnapshot(text), null);
});

test('deal names use the exact UTF-16, empty and line-break rules', () => {
  assert.equal(DEAL_NAME_MAX_LENGTH, 40);
  assert.equal(isValidDealName('x'.repeat(40)), true);
  assert.equal(isValidDealName('🙂'.repeat(20)), true);
  assert.equal(isValidDealName('x'.repeat(41)), false);
  assert.equal(isValidDealName('🙂'.repeat(21)), false);
  assert.equal(isValidDealName(''), false);
  assert.equal(isValidDealName('two\nlines'), false);
  assert.equal(isValidDealName('two\rlines'), false);
  assert.equal(isValidDealName(' \t '), true);
  assert.equal(isValidDealName(null), false);
  assert.equal(isValidDealName(4), false);
});

import { createGame, MOVES_MAX, ELAPSED_MAX_MS } from './game.ts';
import { parseBoardCode } from './deck.ts';
import {
  hasExactKeys,
  isJsonObject,
  isNonnegativeSafeInteger,
  isWithinBytes,
  parseJson,
} from './saved-format.ts';
import { readMatched, readSelection } from './snapshot-selection.ts';
import { isValidDealName } from './deal-name.ts';
import { SelectionKind } from './selection.ts';
import type { GameState } from './game.ts';

export const SNAPSHOT_VERSION = 1;
export const NAMED_SNAPSHOT_VERSION = 2;
export const SNAPSHOT_MAX_BYTES = 65_536;
export const SNAPSHOT_KEYS = [
  'version',
  'boardCode',
  'matched',
  'selection',
  'moves',
  'elapsedMs',
  'started',
] as const;

export function encodeSnapshot(state: GameState): string {
  const progress = {
    boardCode: state.boardCode,
    matched: [...state.matched].sort((left, right) => left - right),
    // Active time keeps its fractions in play. Export writes whole milliseconds, and rounding
    // pending time up keeps a mismatch at 1ms or more.
    selection:
      state.selection.kind === SelectionKind.mismatch
        ? { ...state.selection, remainingMs: Math.ceil(state.selection.remainingMs) }
        : state.selection,
    moves: state.moves,
    elapsedMs: Math.floor(state.elapsedMs),
    started: state.started,
  };
  const snapshot = state.name
    ? { version: NAMED_SNAPSHOT_VERSION, name: state.name, ...progress }
    : { version: SNAPSHOT_VERSION, ...progress };
  return JSON.stringify(snapshot, null, 2);
}

export function decodeSnapshot(text: string): GameState | null {
  const value = isWithinBytes(text, SNAPSHOT_MAX_BYTES) ? parseJson(text) : undefined;
  if (!isJsonObject(value)) return null;
  const named = value.version === NAMED_SNAPSHOT_VERSION;
  const keys = named ? [...SNAPSHOT_KEYS, 'name'] : SNAPSHOT_KEYS;
  if (value.version !== SNAPSHOT_VERSION && !named) return null;
  if (!hasExactKeys(value, keys)) return null;
  let name = '';
  if (named) {
    if (!isValidDealName(value.name)) return null;
    name = value.name;
  }
  if (typeof value.boardCode !== 'string' || !parseBoardCode(value.boardCode)) return null;
  if (
    !isNonnegativeSafeInteger(value.moves) ||
    value.moves > MOVES_MAX ||
    !isNonnegativeSafeInteger(value.elapsedMs) ||
    value.elapsedMs > ELAPSED_MAX_MS ||
    typeof value.started !== 'boolean'
  )
    return null;
  const initial = createGame(value.boardCode);
  const matched = readMatched(value.matched, initial);
  if (!matched) return null;
  const selection = readSelection(value.selection, initial, matched);
  if (!selection) return null;
  const state: GameState = {
    ...initial,
    name,
    matched,
    selection,
    moves: value.moves,
    elapsedMs: value.elapsedMs,
    started: value.started,
  };
  const minimumMoves = matched.length / 2 + (selection.kind === SelectionKind.mismatch ? 1 : 0);
  if (state.moves < minimumMoves) return null;
  if (
    !state.started &&
    (state.moves !== 0 ||
      state.elapsedMs !== 0 ||
      matched.length !== 0 ||
      selection.kind !== SelectionKind.closed)
  )
    return null;
  if (state.started && state.moves === 0 && selection.kind === SelectionKind.closed) return null;
  return state;
}

